package defalt.config

import defalt.models.AuthenticatedUser
import org.springdoc.core.customizers.GlobalOpenApiCustomizer
import org.springdoc.core.customizers.OperationCustomizer
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration

/** Customizes the OpenAPI document generated by springdoc. */
@Configuration
class OpenApiConfig {
    /**
     * Names the tags after the controllers without their `-controller` suffix (`account-controller` -> `account`).
     *
     * @return the customizer renaming the tags of the OpenAPI document.
     */
    @Bean
    fun customizeControllerTags(): GlobalOpenApiCustomizer =
        GlobalOpenApiCustomizer { openApi ->

            openApi.paths?.values?.forEach { pathItem ->

                pathItem.readOperations().forEach { operation ->

                    operation.tags =
                        operation.tags
                            ?.map { tag ->
                                tag.removeSuffix("-controller")
                            }
                }
            }
        }

    /**
     * Hides the `authenticatedUser` parameter of the endpoints: it is resolved from the access token
     * (see `@CurrentUser`), not sent by the client.
     *
     * @return the customizer removing the `authenticatedUser` parameter from the operations.
     */
    @Bean
    fun authenticatedUserOperationCustomizer(): OperationCustomizer =
        OperationCustomizer { operation, handlerMethod ->

            val hasCurrentUser =
                handlerMethod.methodParameters.any {
                    it.parameterType == AuthenticatedUser::class.java
                }

            if (hasCurrentUser) {
                operation.parameters?.removeIf { parameter ->
                    parameter.name == "authenticatedUser"
                }
            }

            operation
        }
}
